class Account:
    def __init__(self, balance):
        self.balance = balance

    def withdraw(self, amount):
        if amount > self.balance:
            raise ValueError("رصيد غير كاف")
        self.balance = self.balance - amount

acc = Account(50)
try:
    acc.withdraw(int(input()))
    print(acc.balance)
except ValueError as e:
    print(e)

